import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(st.nextToken());
        }
        int[] arr_mod = new int[n];
        for (int i = 0; i < n; i++) {
            arr_mod[i] = arr[i] % k;
        }
        if (n == 1) {
            System.out.println(arr_mod[0]);
            return;
        }
        List<Integer> part1 = new ArrayList<>();
        List<Integer> part2 = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
            part1.add(arr_mod[i]);
        }
        for (int i = n / 2; i < n; i++) {
            part2.add(arr_mod[i]);
        }
        Set<Integer> setA = new HashSet<>();
        Set<Integer> setB = new HashSet<>();
        for (int val : part1) {
            Set<Integer> tempSetB = new HashSet<>();
            for (int prev : setA) {
                setB.add((prev + val) % k);
            }
            setA.add(val);
            for (int prev : setB) {
                setA.add(prev);
            }
            setB.clear();
        }
        for (int val : part2) {
            Set<Integer> tempSetB = new HashSet<>();
            for (int prev : setB) {
                tempSetB.add((prev + val) % k);
            }
            setB.addAll(tempSetB);
            setB.addAll(setA);
        }
        List<Integer> list_s = new ArrayList<>(setA);
        List<Integer> list_s1 = new ArrayList<>(setB);
        Collections.sort(list_s);
        Collections.sort(list_s1);
        int max_value = Math.max(Collections.max(list_s), Collections.max(list_s1));
        int res = max_value;
        for (int s_elem : list_s) {
            int target = k - 1 - s_elem;
            int idx = upperBound(list_s1, target);
            if (idx > 0) {
                int r = list_s1.get(idx - 1);
                int rt = list_s1.get(list_s1.size() - 1);
                int candidate1 = (r + s_elem) % k;
                int candidate2 = (s_elem + rt) % k;
                res = Math.max(res, Math.max(candidate1, candidate2));
            }
        }
        System.out.println(res);
    }

    private static int upperBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) <= target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}
